WITH unpacked AS (SELECT id, plan, effective_from, tier_limits, ZIP_WITH(tier_prices, discounts, (p, d) -> ROUND(p * (1 - d), 2)) AS net_prices, AGGREGATE(tier_prices, 0.0D, (acc, p) -> acc + p, acc -> ROUND(acc / SIZE(tier_prices), 2)) AS avg_tier_price, ELEMENT_AT(tier_prices, 1) AS entry_price, ARRAY_MIN(tier_prices) AS lowest_price FROM price_tiers) SELECT plan, DATE_TRUNC('QUARTER', effective_from) AS quarter_start, COUNT(DISTINCT plan) AS distinct_plans, COUNT(CASE WHEN plan = 'pro' THEN 1 END) AS pro_count, SUM(CASE WHEN plan = 'starter' THEN avg_tier_price ELSE 0 END) AS starter_avg_tier_price, ROUND(AVG(entry_price), 2) AS avg_entry_price, PERCENT_RANK() OVER (PARTITION BY plan ORDER BY SUM(CASE WHEN plan = 'starter' THEN avg_tier_price ELSE 0 END) DESC) AS starter_avg_tier_price_percent_rank FROM unpacked GROUP BY plan, quarter_start;
